// Regression: the engine must reproduce the numbers it gave before the v2 interface redesign
// (tests/fixtures/twodes-golden.json, generated by tests/make-twodes-golden.js on the v1.1 engine).
// Run: node --test tests/*.test.js
const test = require("node:test");
const assert = require("node:assert");
const D = require("../assets/js/twodes-core.js");
const G = require("./fixtures/twodes-golden.json");

const close = (got, exp, scale, what) => assert.ok(Math.abs(got - exp) <= 1e-9 * Math.max(Math.abs(scale), 1e-300), `${what}: ${got} != ${exp}`);
function check(name, S, g) {
  if (!g) { assert.strictEqual(S, null, `${name}: expected no spectrum`); return; }
  assert.ok(S, `${name}: spectrum missing`);
  assert.strictEqual(S.N1, g.N1); assert.strictEqual(S.N3, g.N3);
  close(S.w1[0], g.w1[0], g.w1[0], `${name} ω1 axis`); close(S.w3[S.N3 - 1], g.w3[1], g.w3[1], `${name} ω3 axis`);
  let sr = 0, si = 0, n2 = 0;
  for (let j = 0; j < S.re.length; j++) { sr += S.re[j]; si += S.im[j]; n2 += S.re[j] ** 2 + S.im[j] ** 2; }
  const scale = Math.sqrt(g.n2);
  close(sr, g.sr, scale, `${name} Σ re`); close(si, g.si, scale, `${name} Σ im`); close(n2, g.n2, g.n2, `${name} Σ |S|²`);
  for (const [j, re, im] of g.samples) { close(S.re[j], re, scale, `${name} re[${j}]`); close(S.im[j], im, scale, `${name} im[${j}]`); }
}

for (const [name, c] of Object.entries(G.cases)) {
  test(`engine regression: ${name}`, () => {
    const r = D.run(c.job);
    check(`${name} R`, r.R, c.R); check(`${name} NR`, r.NR, c.NR); check(`${name} total`, r.total, c.total);
    assert.deepStrictEqual(r.warnings, c.warnings);
  });
}

test("engine regression: coherence maps", () => {
  const info = D.cmPrepare(G.cm.job, G.cm.opts), M = D.cmMaps(G.cm.wT), sum = (a) => a.reduce((s, x) => s + x, 0);
  info.tau.forEach((t, i) => close(t, G.cm.tau[i], G.cm.tau[i], "fitted τ"));
  close(sum(M.real), G.cm.real, G.cm.real, "real CM"); close(sum(M.pos), G.cm.pos, G.cm.pos, "+ω_T CM"); close(sum(M.neg), G.cm.neg, G.cm.neg, "−ω_T CM");
});
